const menuButton=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');
if(menuButton&&nav){menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));menuButton.textContent=open?'×':'☰';});document.querySelectorAll('.nav a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.textContent='☰';}));}
const year=document.getElementById('year');if(year)year.textContent=new Date().getFullYear();
const ownerProfile='data:image/jpeg;base64,';
const groupPhoto='data:image/jpeg;base64,';
const ownerAvatar=document.getElementById('ownerAvatar');if(ownerAvatar)ownerAvatar.innerHTML='<img src="'+ownerProfile+'" alt="Kishore — owner of Kishore Studios" loading="eager">';
const groupPhoto='data:image/jpeg;base64,';
const cfg=window.KS_CONFIG,canLoad=cfg&&cfg.supabaseUrl&&cfg.supabaseAnonKey&&!String(cfg.supabaseAnonKey).includes('PASTE_');
if(canLoad&&window.supabase){const client=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);loadPublicGallery(client);}
async function loadPublicGallery(client){const c=document.getElementById('liveGallery'),status=document.getElementById('galleryStatus');if(!c)return;try{const r=await client.from('gallery').select('id,public_id,secure_url,resource_type,title,category').order('created_at',{ascending:false});if(r.error)throw r.error;const items=r.data||[],cards=[];cards.push('<figure class="gallery-item wide"><img src="'+groupPhoto+'" alt="Kishore with his team" loading="lazy"><figcaption>Kishore Studios — Team Memories</figcaption></figure>');items.forEach((item,index)=>{const media=item.resource_type==='video'?'<video src="'+esc(item.secure_url)+'" controls muted playsinline preload="metadata"></video>':'<img src="'+esc(item.secure_url)+'" alt="'+esc(item.title||'Kishore Studios photograph')+'" loading="lazy">';const layout=index%5===0?' tall':(index%5===4?' wide':'');cards.push('<figure class="gallery-item'+layout+'">'+media+'<figcaption>'+esc(item.title||item.category||'Kishore Studios')+'</figcaption></figure>');});if(cards.length){c.innerHTML=cards.join('');if(status)status.textContent=(items.length+1)+' memories from Kishore Studios.';}}catch(e){console.error('Gallery load error:',e);if(status)status.textContent='Selected work from Kishore Studios.';}}
function esc(v){return String(v??'').replace(/[&<>\'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
